// Runs a curated subset of the "Security Module" folder from the Postman collection via Newman.
//
// Three requests in that folder ("Reset Password", "Login with Magic Link", "Verify Email")
// carry hardcoded tokens copy-pasted from real emails during manual testing — those tokens are
// per-run random strings generated by AuthService, so they can never match a fresh CI database
// and would always fail regardless of whether the app itself is correct. They're excluded here
// rather than edited out of the source collection file, so the collection stays exactly as-is
// for manual Postman use (e.g. the maintainer pasting in a real token from their inbox).
//
// This filters the collection in-memory and drives Newman's Node API directly, since Newman's
// CLI --folder flag only supports whole-folder granularity, not excluding individual requests.
const fs = require("fs");
const path = require("path");
const newman = require("newman");

const REPO_ROOT = path.resolve(__dirname, "..", "..");
const COLLECTION_PATH = path.join(REPO_ROOT, "postman", "collection.json");
const ENVIRONMENT_PATH = path.join(REPO_ROOT, "postman", "environment.json");

const EXCLUDED_REQUEST_NAMES = new Set([
  "[API] Reset Password",
  "[API] Login with Magic Link",
  "[API] Verify Email",
]);

const collection = JSON.parse(fs.readFileSync(COLLECTION_PATH, "utf-8"));

const securityFolder = collection.item.find((item) => item.name === "Security Module");
if (!securityFolder) {
  console.error("Could not find 'Security Module' folder in the collection");
  process.exit(1);
}

securityFolder.item = securityFolder.item.filter(
  (request) => !EXCLUDED_REQUEST_NAMES.has(request.name)
);

console.log(
  "Running Security Module requests:",
  securityFolder.item.map((r) => r.name).join(", ")
);

newman.run(
  {
    collection: { item: [securityFolder], info: collection.info },
    environment: JSON.parse(fs.readFileSync(ENVIRONMENT_PATH, "utf-8")),
    envVar: [{ key: "base_url", value: "http://localhost:8080/v1/api" }],
    reporters: ["cli", "junit"],
    reporter: { junit: { export: path.join(REPO_ROOT, "newman-report.xml") } },
  },
  (err, summary) => {
    if (err) {
      console.error("Newman run errored:", err);
      process.exit(1);
    }
    if (summary.run.failures.length > 0) {
      console.error(`${summary.run.failures.length} request(s) failed`);
      process.exit(1);
    }
    console.log("All Security Module E2E requests passed");
  }
);
